INSERT INTO attribute_desc VALUES(1001,1002,'en','<3,0,1>','Signature for the flat tensor h','$h_{p}$ has a 4x4 matrix of components $(h^{ij})$ in every coordinate system $\left\langle x_{i}\right\rangle $, and we can always find system in which $(h^{ij})$ is diagonalized with all diagonal elements equal to +1, -1, or zero. The triple  $\left\langle n_{+} n_{-},n_{0}\right\rangle $ where $n_{0}$ is the number of vanishing diagonal elements, is the signature of $h_{p}$.',NULL);
INSERT INTO attribute_desc VALUES(1001,1002,'es','<3,0,1>','Signatura del tensor plano h','$h_{p}$ tiene una matriz de componentes 4x4 ($h^{ij}$) en cada sistema de coordenadas $\left\langle x_{i}\right\rangle $, y siempre podemos encontrar el sistema en el cual ($ h^{ij}$) está diagonalizado con todos los elementos diagonales iguales a +1, -1 o cero. La tripleta $\left\langle n_{+} n_{-},n_{0}\right\rangle $ donde $n_{0}$ es el número de elementos diagonales que desaparecen, es la signatura de $h_{p}$.',NULL);
INSERT INTO attribute_desc VALUES(1002,1002,'en','epsilon=1','$\epsilon=1$',NULL,NULL);
INSERT INTO attribute_desc VALUES(1002,1002,'es','$\epsilon = 1$','$\epsilon=1$',NULL,NULL);
INSERT INTO attribute_desc VALUES(1003,1002,'en','epsilon','$\epsilon$: Arbitrary function',NULL,NULL);
INSERT INTO attribute_desc VALUES(1003,1002,'es','$\epsilon$','$\epsilon$: Función arbitraria',NULL,NULL);
INSERT INTO attribute_desc VALUES(1004,1002,'en','epsilon=0','$\epsilon=0$',NULL,NULL);
INSERT INTO attribute_desc VALUES(1004,1002,'es','$\epsilon = 0$','$\epsilon=0$',NULL,NULL);
INSERT INTO attribute_desc VALUES(1005,1002,'en','a, b, c, d','$a$, $b$, $c$, $d$','Cosmological matching parameters.',NULL);
INSERT INTO attribute_desc VALUES(1005,1002,'es','a, b, c, d','$a$, $b$, $c$, $d$','Parámetros de coincidencia cosmológica.',NULL);
INSERT INTO attribute_desc VALUES(1006,1002,'en','a, f, k','Arbitrary parameters',NULL,NULL);
INSERT INTO attribute_desc VALUES(1006,1002,'es','a, f, k','Parámetros arbitrarios',NULL,NULL);
INSERT INTO attribute_desc VALUES(1007,1002,'en','a0','Milgrom’s constant','Acceleration scale. Sistems experiencing accelerations lower than $a_{0}$ will present not standard dynamics.',NULL);
INSERT INTO attribute_desc VALUES(1007,1002,'es','a0','Constante de Milgrom','Escala de aceleración. Los sistemas que experimenten aceleraciones menores a $a_{0}$ mostrarán una dinámica no estándar.',NULL);
INSERT INTO attribute_desc VALUES(1008,1002,'en','Affine Connection','$\Gamma$: Affine connection','In the absence of a metric tensor field, A generalised connection for vector fields decomposes into irreducible components, where $B$ field is the traceless part of the torsion, $A_{\mu}$ is the trace of the torsion and $\hat{\Gamma}_{\left(\mu\nu\right)}^{\lambda}=\Gamma_{\mu\nu}^{\lambda}$ is a renaming of the symmetric part of the affine connection.',NULL);
INSERT INTO attribute_desc VALUES(1008,1002,'es','Conexión Afín','$\Gamma$: Conexión afín','En ausencia de un campo tensor métrico, una conexión generalizada para campos vectoriales se descompone en componentes irreducibles, donde el campo $B$ es la parte sin rastro de la torsión, $A_{\mu}$ es la traza de la torsión y $\hat{ \Gamma}_{\left(\mu\nu\right)}^{\lambda}=\Gamma_{\mu\nu}^{\lambda}$ es el nuevo nombre de la parte simétrica de la conexión afín.',NULL);
INSERT INTO attribute_desc VALUES(1009,1002,'en','B','$B$: Symmetric tensor field','The symmetric tensor field $B$ is typically associated with the presence of multiple metrics, which describe how distances and intervals are measured in different ways. In stratified and bimetric theories there might be two or more metrics to describe different aspects of gravity or spacetime such as variations in gravity''s strength or range. $B$ helps relate and reconcile these metrics, ensuring that the theory remains self-consistent.',NULL);
INSERT INTO attribute_desc VALUES(1009,1002,'es','B','$B$: Campo tensorial simétrico','El campo tensorial simétrico $B$ normalmente se asocia con la presencia de múltiples métricas, que describen cómo se miden las distancias y los intervalos de diferentes maneras. En las teorías estratificadas y bimétricas puede haber dos o más métricas para describir diferentes aspectos de la gravedad o el espacio-tiempo, como las variaciones en la fuerza o el alcance de la gravedad. $B$ ayuda a relacionar y conciliar estas métricas, asegurando que la teoría siga siendo autoconsistente.',NULL);
INSERT INTO attribute_desc VALUES(1010,1002,'en','c','$c$: Light speed','The invariance of the velocity of electromagnetic signals. Light has the same constant velocity in all inertial reference frames.',NULL);
INSERT INTO attribute_desc VALUES(1010,1002,'es','c','$c$: Velocidad de la luz','Invariancia de la velocidad de señales electromagnéticas. La luz tiene la misma velocidad en todas los marcos de referencia inerciales.',NULL);
INSERT INTO attribute_desc VALUES(1011,1002,'en','c0, c1','$C_{0}$, $C_{1}$: Cosmological matching parameters','In the universe rest frame, g has the asymptotic form $diag(-c_{0},c_{1},c_{1},c_{1})$, where $c_{0}$ and $c_{1}$  may vary on a Hubble timescale. ',NULL);
INSERT INTO attribute_desc VALUES(1011,1002,'es','c0, c1','$C_{0}$, $C_{1}$','Parámetros cosmológicos. En el marco de reposo del universo, g tiene la forma asintótica $diag(-c_{0},c_{1},c_{1},c_{1})$, donde $c_{0}$ y $c_{1 }$ pueden variar en la escala de tiempo del Hubble.',NULL);
INSERT INTO attribute_desc VALUES(1012,1002,'en','Class D','Class of Connection',NULL,NULL);
INSERT INTO attribute_desc VALUES(1012,1002,'es','Clase D','Clase de conexión',NULL,NULL);
INSERT INTO attribute_desc VALUES(1013,1002,'en','Closed','Closed space',NULL,NULL);
INSERT INTO attribute_desc VALUES(1013,1002,'es','Cerrado','Espacio cerrado',NULL,NULL);
INSERT INTO attribute_desc VALUES(1014,1002,'en','Confromal transformations','Conformal transformations',NULL,NULL);
INSERT INTO attribute_desc VALUES(1014,1002,'es','Transformaciones conformes','Transformaciones conformes',NULL,NULL);
INSERT INTO attribute_desc VALUES(1015,1002,'en','Cosmic time','Cosmic time',NULL,NULL);
INSERT INTO attribute_desc VALUES(1015,1002,'es','Tiempo cósmico','Tiempo cósmico',NULL,NULL);
INSERT INTO attribute_desc VALUES(1016,1002,'en','Curvature','Riemann curvature tensor','The curvature tensor of an affine connection is a linear transformation-valued tensor field assigning a mapping to each pair of vectors at $p.$',NULL);
INSERT INTO attribute_desc VALUES(1016,1002,'es','Curvatura','Tensor de curvatura de Riemann','El tensor de curvatura de una conexión afín es un campo tensorial con valor de transformación lineal que asigna un mapeo a cada par de vectores en $p.$',NULL);
INSERT INTO attribute_desc VALUES(1017,1002,'en','Curvature = 0','Curvature = 0','Riemann’s curvature tensor of the affine connection is zero. Found as $K=0$ in Friedman.',NULL);
INSERT INTO attribute_desc VALUES(1017,1002,'es','Curvatura = 0','Curvatura = 0','El tensor de curvatura de Riemann es cero en todo el espacio. En Will se le encuentra como $K=0$.',NULL);
INSERT INTO attribute_desc VALUES(1018,1002,'en','D(dt) = 0','Flat simultaneity slices','Covariant derivative of $dt$ equals zero to ensure the simultaneity slices are flat.',NULL);
INSERT INTO attribute_desc VALUES(1018,1002,'es','D(dt) = 0','Cortes de simultaneidad planos','La derivada covariante igual a cero asegura que los cortes de simultaneidad sean planos.',NULL);
INSERT INTO attribute_desc VALUES(1019,1002,'en','D(g) = 0','Covariant constancy of the metric','The covariant derivative acting on the metric tensor vanishes. Condition that preserves angles and distances when parallel transporting vectors along a curve.',NULL);
INSERT INTO attribute_desc VALUES(1019,1002,'es','D(g) = 0','Constancia covariante de la métrica','La derivada covariante del tensor métrico se desvanece. Condición que preserva ángulos y distancias cuando se transporta de forma paralela un vector a lo largo de una curva.',NULL);
INSERT INTO attribute_desc VALUES(1020,1002,'en','D(h) = 0','Constancy of the flat metric','Local field equation: the flat metric h is compatible with the flat connection $\overline{D}$, describing euclidean geometry.',NULL);
INSERT INTO attribute_desc VALUES(1020,1002,'es','D(h) = 0','Constancia de la métrica plana','La derivada covariante de h describe la geometría euclidiana.',NULL);
INSERT INTO attribute_desc VALUES(1021,1002,'en','D(V) = 0','Covariant constancy of V','Covariant derivative of the vector field V equals zero. It makes the lines in the rigging of space-time to be geodesics, meaning that V remains unchanged or constant as it moves along these paths.',NULL);
INSERT INTO attribute_desc VALUES(1021,1002,'es','D(V) = 0','Constancia covariante de V','Que la derivada covariante de $V$ sea igual a cero hace que las líneas en el aparejo del espacio-tiempo sean geodésicas.',NULL);
INSERT INTO attribute_desc VALUES(1022,1002,'en','Definite-Positive','Class of signature','The class of signature of the metric tensor is all positive $<+,+,+,+>$, characteristic of other mathematical and non-physical spaces.',NULL);
INSERT INTO attribute_desc VALUES(1022,1002,'es','Signatura Positiva','Clase de signatura','La signatura del tensor métrico es toda positiva $<+,+,+,+>$, propia de otros espacios matemáticos y no físicos.',NULL);
INSERT INTO attribute_desc VALUES(1023,1002,'en','Density','Density field',NULL,NULL);
INSERT INTO attribute_desc VALUES(1023,1002,'es','Densidad','Densidad',NULL,NULL);
INSERT INTO attribute_desc VALUES(1024,1002,'en','Dependent','Dependency','The connection $\Gamma_{\mu\nu}^{\lambda}$  and the metric tensor $g_{\mu\nu}$  depend on each other.',NULL);
INSERT INTO attribute_desc VALUES(1024,1002,'es','Dependiente','Dependencia entre variables','La conexión  $\Gamma_{\mu\nu}^{\lambda}$ y el tensor métrico $g_{\mu\nu}$ dependen uno del otro.',NULL);
INSERT INTO attribute_desc VALUES(1025,1002,'en','Diff','Diffeomorphism Invariance','A theory is diffeomorphism invariant if its physical content is unchanged under arbitrary smooth transformations of the spacetime manifold. The spacetime geometry is not fixed a priori but is transformed together with the dynamical fields. This property is closely related to background independence.',NULL);
INSERT INTO attribute_desc VALUES(1025,1002,'es','Dif','Invariancia por Difeomorfismos','Una teoría es invariante por difeomorfismos si su contenido físico permanece inalterado bajo transformaciones suaves arbitrarias del espacio-tiempo. La geometría del espacio-tiempo no está fijada de antemano, sino que se transforma junto con los campos dinámicos. Esta propiedad está estrechamente relacionada con la independencia del trasfondo (background independence).',NULL);
INSERT INTO attribute_desc VALUES(1026,1002,'en','dsGR','General line element for GR',NULL,NULL);
INSERT INTO attribute_desc VALUES(1026,1002,'es','dsGR','Elemento de línea general',NULL,NULL);
INSERT INTO attribute_desc VALUES(1027,1002,'en','dt','$dt$: Time function','Co-vector that induces a foliation of $M$ into three-dimensional hyper surfaces.',NULL);
INSERT INTO attribute_desc VALUES(1027,1002,'es','dt','$dt$: Función de tiempo','Un covector que induce una foliación de la variedad M en hyper-superficies de tres dimensiones.',NULL);
INSERT INTO attribute_desc VALUES(1028,1002,'en','dt x k = 0','Temporal geometry constraint','This field equation imposes a constraint on the temporal geometry, specifying that it remains unaffected by the Riemann curvature tensor ($K$ in Friedman).',NULL);
INSERT INTO attribute_desc VALUES(1028,1002,'es','dt x k =0','Constricción en la geometría temporal','Esta ecuación de campo impone restricciones a la geometría temporal, especificando que no es afectada por el tensor de curvatura de Riemann ($K$ en Friedman).',NULL);
INSERT INTO attribute_desc VALUES(1029,1002,'en','dt(V) = 1','Requirement for Timelike Curves','This condition is introduced to ensure that the curves $\sigma$ are timelike. The quantity $dt(V)$ represents the rate of change of time along the curves as experienced by an observer moving along V. Requiring $dt(V)=1$ ensures that the curves are moving forward in time according to the standard absolute time.',NULL);
INSERT INTO attribute_desc VALUES(1029,1002,'es','dt(V) = 1','Requisito de curvas temporales','Esta condición se introduce para garantizar que las curvas $\sigma$ sean temporales. La cantidad $dt(V)$ representa la tasa de cambio del tiempo a lo largo de las curvas experimentada por un observador que se mueve a lo largo de V. Requerir $dt(V)=1$ garantiza que las curvas avancen en el tiempo de acuerdo con el tiempo absoluto estándar.',NULL);
INSERT INTO attribute_desc VALUES(1030,1002,'en','Dust','Dust',NULL,NULL);
INSERT INTO attribute_desc VALUES(1030,1002,'es','Polvo','Polvo',NULL,NULL);
INSERT INTO attribute_desc VALUES(1031,1002,'en','Einstein’s Eq','Einstein’s field equation','It relates the curvature of space-time with the distribution of matter and energy within it. $\mathbf{Ric}$ is the Ricci curvature tensor, $R$ is the scalar curvature and $\mathbf{T}$ is the stress-energy-momentum tensor. ',NULL);
INSERT INTO attribute_desc VALUES(1031,1002,'es','Ec. de Einstein','Ecuación de Einstein','Relaciona la curvatura del espacio-tiempo con la distribución de materia y energía. $\mathbf{Ric}$ es el tensor de Ricci, $R$ es el escalar de curvatura y $\mathbf{T}$ es el tensor de estrés-energía-momentum.',NULL);
INSERT INTO attribute_desc VALUES(1032,1002,'en','epsilon2','$\epsilon$','Arbitrary parameter.',NULL);
INSERT INTO attribute_desc VALUES(1032,1002,'es','epsilon2','$\epsilon$','Parámetro arbitrario.',NULL);
INSERT INTO attribute_desc VALUES(1033,1002,'en','Eq 13','Palatini action','The metric and connection are independent. Variation not on the connection. Note the new Ricci tensor is constructed with an independent connection:  $\Re=g_{\mu\nu}R_{\mu\nu}$.',NULL);
INSERT INTO attribute_desc VALUES(1033,1002,'es','Ec. 13','Acción a la Palatini','La métrica y la conexión son independientes. No se varía sobre la conexión. Note que el nuevo tensor de Ricci es construido independientemente de la conexión: $\Re=g_{\mu\nu}R_{\mu\nu}$.',NULL);
INSERT INTO attribute_desc VALUES(1034,1002,'en','Eq 13M','Eq 13M','Field equation for MoND local F(R,T).',NULL);
INSERT INTO attribute_desc VALUES(1034,1002,'es','Ec. 13M','Ec. 13M','Ecuación de campo para la teoría extendida tipo MoND local F(R,T).',NULL);
INSERT INTO attribute_desc VALUES(1035,1002,'en','Eq 14M','Eq 14M','Field equation for Mond non local pure Metric.',NULL);
INSERT INTO attribute_desc VALUES(1035,1002,'es','Ec. 14M','Ec. 14M','Ecuación de campo para la teoría extendida tipo MoND no-local con métrica pura.',NULL);
INSERT INTO attribute_desc VALUES(1036,1002,'en','Eq 18','Eq 18','Palatini field equation 1.',NULL);
INSERT INTO attribute_desc VALUES(1036,1002,'es','Ec. 18','Ec. 18','Ecuación de campo a la Palatini 1.',NULL);
INSERT INTO attribute_desc VALUES(1037,1002,'en','Eq 18M','Eq 18M','Equation of motion for MoNDian non local pure metric extended theory.',NULL);
INSERT INTO attribute_desc VALUES(1037,1002,'es','Ec. 18M','Ec. 18M','Ecuación de movimiento de la teoría extendida tipo MoND no-local con métrica pura.',NULL);
INSERT INTO attribute_desc VALUES(1038,1002,'en','Eq 19','Eq 19','Palatini field equation 2. ($\bar{\nabla}_{\lambda}$) is the covariant derivative defined with the independent connection.',NULL);
INSERT INTO attribute_desc VALUES(1038,1002,'es','Ec. 19','Ec. 19','La ecuación de campo a la Palatini $\bar{\nabla}$ es la derivada covariante definida de forma independiente o mediante la conexión métrico-afín.',NULL);
INSERT INTO attribute_desc VALUES(1039,1002,'en','Eq 2M','Eq 2M','Equation of motion for the MoNDian non-local a la palatini extended theory.',NULL);
INSERT INTO attribute_desc VALUES(1039,1002,'es','Ec. 2M','Ec. 2M','Ecuación de movimiento de la teoría extendida no-local a la Palatini tipo MoND.',NULL);
INSERT INTO attribute_desc VALUES(1040,1002,'en','Eq 34M, 35M','Eq 34M, 35M','Equation of motion for MoND local pure metric.',NULL);
INSERT INTO attribute_desc VALUES(1040,1002,'es','Ec. 34M, 35M','Ec. 34M, 35M','Ecuación de movimiento para la teoría extendida tipo MoND local con métrica pura.',NULL);
INSERT INTO attribute_desc VALUES(1041,1002,'en','Eq 37M','Eq 37M','Equation of motion for MoND F(R,T).',NULL);
INSERT INTO attribute_desc VALUES(1041,1002,'es','Ec. 37M','Ec. 37','Ecuación de movimiento de la teoría extendida F(R,T).',NULL);
INSERT INTO attribute_desc VALUES(1042,1002,'en','Eq 46','Eq 46','Field equation.',NULL);
INSERT INTO attribute_desc VALUES(1042,1002,'es','Ec. 46','Ec. 46','Ecuación de campo tras variar de manera independiente con respecto a la métrica.',NULL);
INSERT INTO attribute_desc VALUES(1043,1002,'en','Eq 47','Eq 47','Field equation after varying independently with respect to the connection.',NULL);
INSERT INTO attribute_desc VALUES(1043,1002,'es','Ec. 47','Ec. 47','Ecuación de campo tras variar de manera independiente con respecto a la conexión afín.',NULL);
INSERT INTO attribute_desc VALUES(1044,1002,'en','Eq 48','Eq 48','Field equation after varying independently with respect to the Lagrange multiplier.',NULL);
INSERT INTO attribute_desc VALUES(1044,1002,'es','Ec. 48','Ec. 48','Ecuación de campo tras variar de manera independiente con respecto al multiplicador de Lagrange.',NULL);
INSERT INTO attribute_desc VALUES(1045,1002,'en','Eq 4M','Eq 4M','Field equation for MoND local pure metric.',NULL);
INSERT INTO attribute_desc VALUES(1045,1002,'es','Ec. 4M','Ec. 4M','Ecuación de campo de la teoría extendida local con métrica pura.',NULL);
INSERT INTO attribute_desc VALUES(1046,1002,'en','Eq 5','Eq 5','Total action for a metric $f(R)$.',NULL);
INSERT INTO attribute_desc VALUES(1046,1002,'es','Ec. 5','Ec. 5','Acción total para la métrica $f(R)$.',NULL);
INSERT INTO attribute_desc VALUES(1047,1002,'en','Eq 5-30','Eq 5-30','Action for scalar-tensor theories.',NULL);
INSERT INTO attribute_desc VALUES(1047,1002,'es','Ec. 5-30','Ec. 5-30','Acción para las teorías escalares-tensoriales',NULL);
INSERT INTO attribute_desc VALUES(1048,1002,'en','Eq 5-31','Eq 5-31','The field equation is derived from the action 5-30.',NULL);
