INSERT INTO attribute_desc VALUES(1059,1002,'en','Eq 6','Eq 6','Field equation of metric  $f(R)$.',NULL);
INSERT INTO attribute_desc VALUES(1059,1002,'es','Ec. 6','Ec. 6','Ecuación de campo de la teoría $f(R)$ métrica',NULL);
INSERT INTO attribute_desc VALUES(1060,1002,'en','Eq 8M','Eq 8M','Field equation for MoND non local Palatini. The null variations of the action with respect to the metric yields this field equation where the dimensionless tensor is $\chi_{\mu\nu}:=L_{M}^{2}R_{\mu\nu}$ and $f''(\chi):=\frac{df(\chi)}{d\chi}$.',NULL);
INSERT INTO attribute_desc VALUES(1060,1002,'es','Ec. 8M','Ec. 8M','Ecuación de campo de la teoría extendida no local a la Palatini. Las variaciones nulas de la acción con respecto a la métrica producen esta ecuación de campo donde el tensor adimensional es $\chi_{\mu\nu}:=L_{M}^{2}R_{\mu\nu}$ y $f ''(\chi):=\frac{df(\chi)}{d\chi}$.',NULL);
INSERT INTO attribute_desc VALUES(1061,1002,'en','Eq 9a','Eq 9a','If the Ricci scalar $R=0$, then the field equation reduces to $R_{\mu\eta}=0$ and the maximally symmetric solution is Minkowski spacetime.',NULL);
INSERT INTO attribute_desc VALUES(1061,1002,'es','Ec. 9a','Ec. 9a','Si el escalar de Ricci es igual a cero: $R=0$ entonces la ecuación de campo se reduce a: $R_{\mu\eta}=0$.',NULL);
INSERT INTO attribute_desc VALUES(1062,1002,'en','Eq 9b','Eq 9b','If the Ricci scalar is constant, then the field equation reduces to $R_{\mu\nu}=g_{\mu\nu}\frac{Const}{4}$, and the maximally symmetric solution is de Sitter or anti-de Sitter space depending on the sign of the constant.',NULL);
INSERT INTO attribute_desc VALUES(1062,1002,'es','Ec. 9b','Ec. 9b','Si el escalar de Ricci es constante: $R=cte$, entonces la ecuación de campo se reduce a: $R_{\mu\nu}=g_{\mu\nu}\frac{C}{4}$, y la solución simétrica máxima es el espacio de de Sitter ó el anti-de Sitter, dependiendo del signo de la constante.',NULL);
INSERT INTO attribute_desc VALUES(1063,1002,'en','Eq 9c','Eq 9c','If the Ricci scalar is constant, then the field equation reduces to $R_{\mu\nu}=g_{\mu\nu}\frac{Const}{4}$, and the maximally symmetric solution is de Sitter or anti-de Sitter space depending on the sign of the constant.',NULL);
INSERT INTO attribute_desc VALUES(1063,1002,'es','Ec. 9c','Ec. 9c','Si el escalar de Ricci es constante: $R=cte$ entonces la ecuación de campo se reduce a: $R_{\mu\nu}=g_{\mu\nu}\frac{C}{4}$ y el la solución máximamente simétrica es de Sitter en el espacio anti-de Sitter, dependiendo del signo de la constante.',NULL);
INSERT INTO attribute_desc VALUES(1064,1002,'en','eta','$\eta$: Minkowski’s metric','Flat non-dynamical metric. Since $Riem(\Gamma)=0$, we can always choose global coordinates in which $\eta_{\mu\nu}=diag(-1,1,1,1)$.',NULL);
INSERT INTO attribute_desc VALUES(1064,1002,'es','eta','$\eta$: Métrica de Minkowski','Métrica plana no dinámica. Dado que $Riem(\Gamma)=0$, siempre podemos elegir coordenadas globales en las que $\eta_{\mu\nu}=diag(-1,1,1,1)$.',NULL);
INSERT INTO attribute_desc VALUES(1065,1002,'en','f’’(R) = 0','$f’’(R)=0$','The second derivative of the function of the Ricci scalar is zero.',NULL);
INSERT INTO attribute_desc VALUES(1065,1002,'es','f’’(R) = 0','$f’’(R) =0$','La segunda derivada de la función del escalar de Ricci es cero.',NULL);
