INSERT INTO attribute_desc VALUES(1067,1002,'es','f’’(R*) = 0','$f’’(R^{*})=0$','La segunda derivada de la función del escalar de Ricci afín es cero.',NULL);
INSERT INTO attribute_desc VALUES(1068,1002,'en','f’’(R†) ≠ 0','$f''''(\Re)≠0$','The second derivative of the function of the affine curvature scalar is not zero.',NULL);
INSERT INTO attribute_desc VALUES(1068,1002,'es','f’’(R*) ≠ 0','$f’’(R^{*})\neq0$','La segunda derivada de la función del escalar de Ricci afín es distinta de cero.',NULL);
