INSERT INTO attribute_desc VALUES(1070,1002,'es','f’(R*) = 1','$f’(R^{*})=1$','La primera derivada del escalar de curvatura afín es igual a uno.',NULL);
INSERT INTO attribute_desc VALUES(1071,1002,'en','F(R,Lm)','$F(R,\mathcal{L}_{matt})$','A class of action functions. The action is a function of the Ricci scalar and the matter Lagrangian.',NULL);
