INSERT INTO attribute_desc VALUES(1075,1002,'es','F(R*,Lm)','$F(\Re,L_{m})$','La acción es una función del escalar de Ricci afín y del Lagrangiano de materia.',NULL);
INSERT INTO attribute_desc VALUES(1076,1002,'en','F(R†,T)','$F(\Re,T_{\mu\nu})$','A class of action functions. The action is also a function of the affine Ricci scalar and the trace of the energy momentum tensor.',NULL);
INSERT INTO attribute_desc VALUES(1076,1002,'es','F(R*,T)','$F(\Re,T_{\mu\nu})$','La acción también puede pensarse en función del escalar de Ricci afín y la traza del tensor de estrés-energía-momento.',NULL);
