INSERT INTO attribute_desc VALUES(1096,1002,'en','Geodesic comoving observers','Geodesic comoving observers','Comoving observers have zero four-acceleration',NULL);
INSERT INTO attribute_desc VALUES(1096,1002,'es','Observadores geodésicos comóviles','Observadores geodésicos comóviles',NULL,NULL);
INSERT INTO attribute_desc VALUES(1097,1002,'en','Geodesic congruence expands','Geodesic congruence expands','Condition on the expansion scalar',NULL);
INSERT INTO attribute_desc VALUES(1097,1002,'es','Congruencia de geodésicas',NULL,NULL,NULL);
INSERT INTO attribute_desc VALUES(1098,1002,'en','Gravitational Force','Gravitational force','Particles acted on only by gravitational forces follow non geodesic paths determined by the gravitational potential.',NULL);
INSERT INTO attribute_desc VALUES(1098,1002,'es','Fuerza Gravitacional','Fuerza Gravitacional','Las partículas afectadas sólo por fuerzas gravitacionales siguen curvas no geodésicas determinadas por el potencial gravitacional.',NULL);
INSERT INTO attribute_desc VALUES(1099,1002,'en','h','Plank’s constant',NULL,NULL);
INSERT INTO attribute_desc VALUES(1099,1002,'es','h','Constante de Plank',NULL,NULL);
INSERT INTO attribute_desc VALUES(1100,1002,'en','h(dt,w) = 0','Temporal orthogonality','An orthogonality condition that describes euclidean geometry.',NULL);
INSERT INTO attribute_desc VALUES(1100,1002,'es','h(dt,w)=0','Ortogonalidad temporal','Condición de ortogonalidad que describe la geometría euclidiana.',NULL);
INSERT INTO attribute_desc VALUES(1101,1002,'en','H2*K = H2*K','Symmetry property','This field equation indicates that the way space curves due to gravitational effects is the same, regardless of the order in which you consider different positions or coordinates.',NULL);
INSERT INTO attribute_desc VALUES(1101,1002,'es','H2*K = H2*K','Propiedad de simetría','Esta ecuación de campo indica que la forma en que el espacio se curva debido a los efectos gravitacionales es la misma, independientemente del orden en que se consideren diferentes posiciones o coordenadas.',NULL);
INSERT INTO attribute_desc VALUES(1102,1002,'en','hab','$h$: Flat Metric tensor','A symmetric tensor field of type $(2,0)$. h is defined on de cotangent space $T_{p}^{*}\times T_{p}^{*}$ and has signature $<3,0,1>$. It induces a three-dimensional metric on each hypersurface.',NULL);
INSERT INTO attribute_desc VALUES(1102,1002,'es','hab','$h$: Tensor métrico plano','Un campo tensor simétrico de tipo $(2,0)$. h se define en el espacio cotangente $T_{p}^{*}\times T_{p}^{*}$ y tiene la signatura $<3,0,1>$. Induce una métrica tridimensional en cada hipersuperficie.',NULL);
INSERT INTO attribute_desc VALUES(1103,1002,'en','Hyp','Hypermomentum','A quantity representing the variation of $S_{M}$ with respect to the connection, which mimics the definition of the stress-energy tensor. ',NULL);
INSERT INTO attribute_desc VALUES(1103,1002,'es','Hyp','Hypermomentum','Cantidad que representa la variación de la acción de materia SM con respecto a la conexión, lo que imita la definición del tensor de estrés-energía-momentum.',NULL);
INSERT INTO attribute_desc VALUES(1104,1002,'en','Independent','Independency between variables','The connection $\Gamma_{\mu\nu}^{\lambda}$ may be expressed independently of the metric tensor $g_{\mu\nu}$.',NULL);
INSERT INTO attribute_desc VALUES(1104,1002,'es','Independente','Independencia de variables','La conexión $\Gamma_{\mu\nu}^{\lambda}$ puede expresarse de forma independiente al tensor métrico $g_{\mu\nu}$.',NULL);
INSERT INTO attribute_desc VALUES(1105,1002,'en','Isotropy','Isotropy','Distribution of galaxies is the same in any direction at large scales',NULL);
INSERT INTO attribute_desc VALUES(1105,1002,'es','Isotropía','Isotropía','La distribución de galaxias es la misma en cualquier dirección a gran escala',NULL);
INSERT INTO attribute_desc VALUES(1106,1002,'en','K0','$K_{0}$','Cosmological matching parameter.',NULL);
INSERT INTO attribute_desc VALUES(1106,1002,'es','K0','$K_{0}$','Parámetro de coincidencia cosmológica.',NULL);
INSERT INTO attribute_desc VALUES(1107,1002,'en','k1 = c3/16piG','Coupling constant',NULL,NULL);
INSERT INTO attribute_desc VALUES(1107,1002,'es','k1 = c3/16piG','Constante de acoplamiento',NULL,NULL);
INSERT INTO attribute_desc VALUES(1108,1002,'en','kappa','$\kappa$ Einstein’s constant','$\kappa$ is a positive real number with dimension $L^{-1}M^{-1}T^{2}$.<br>$\kappa$ represents the coupling of $\sigma$ with $\bar{\sigma}$.',NULL);
INSERT INTO attribute_desc VALUES(1108,1002,'es','kappa','$\kappa$: constante de Einstein','$\kappa$ es un número real positivo con dimensión $L^{-1}M^{-1}T^{2}$.<br>$\kappa$ representa el acoplamiento de $\sigma$ con $\bar{\sigma}$.',NULL);
INSERT INTO attribute_desc VALUES(1109,1002,'en','Kappa1, Kappa2','Arbitrary functions',NULL,NULL);
INSERT INTO attribute_desc VALUES(1109,1002,'es','Kappa1, Kappa2','$\kappa_{1}$, $\kappa_{2}$: Funciones arbitrarias',NULL,NULL);
INSERT INTO attribute_desc VALUES(1110,1002,'en','Km','$K^{\mu}$: Dynamical vector field','Timelike dynamic vector field.',NULL);
INSERT INTO attribute_desc VALUES(1110,1002,'es','Km','$K^{\mu}$: Campo vectorial dinámico','Campo vectorial dinámico tipo tiempo.',NULL);
INSERT INTO attribute_desc VALUES(1111,1002,'en','Locality','Locality','The action is a local function of the fields and finitely many of their derivatives.',NULL);
INSERT INTO attribute_desc VALUES(1111,1002,'es','Localidad','Localidad','La acción es una función local de los campos y de sus derivadas.',NULL);
INSERT INTO attribute_desc VALUES(1112,1002,'en','Lorentz boost','Lorentz boost',NULL,NULL);
INSERT INTO attribute_desc VALUES(1112,1002,'es','Impulso de Lorentz','Impulso de Lorentz',NULL,NULL);
INSERT INTO attribute_desc VALUES(1113,1002,'en','M','$M$: Differentiable manifold','1.- Space-time has topology: given any point $p$ in space-time, we have the notion of a neighborhood of $p$.<br>2.- Space-time is coordinatizable by $R^{4}$. This is a purely local assertion (space-time is locally euclidean).',NULL);
INSERT INTO attribute_desc VALUES(1113,1002,'es','M','$M$: Variedad diferenciable','El espacio-tiempo tiene topología: dado cualquier punto $p$ en el espacio-tiempo, tenemos la noción de una vecindad de $p$.<br> 2.- El espacio-tiempo es coordinable por $R^{4}$. Ésta es una afirmación puramente local (el espacio-tiempo es localmente euclidiano).',NULL);
INSERT INTO attribute_desc VALUES(1114,1002,'en','Mass','$M$: Mass','A function from $\Sigma$ to the set $\mathbb{R^{+}}$ of non-negative reals.<br>The value of $M$ in $\sigma,\in\Sigma$ represents the mass (inertia) of $\sigma$.',NULL);
INSERT INTO attribute_desc VALUES(1114,1002,'es','Masa','$M$: masa','Función de $\Sigma$ al conjunto $\mathbb{R^{+}}$ de reales no negativos.<br>El valor de $M$ en $\sigma,\in\Sigma$ representa la masa (inertia) de $\sigma$.',NULL);
INSERT INTO attribute_desc VALUES(1115,1002,'en','Maximally symmetric','Maximally symmetric','A spacetime is maximally symmetric if it possesses the largest possible number of continuous spacetime symmetries (Killing vector fields) for its dimension. In four dimensions, a maximally symmetric spacetime has 10 independent Killing vectors and constant sectional curvature. Minkowski, de Sitter, and anti-de Sitter spacetimes are the three maximally symmetric solutions of Einstein''s equations.',NULL);
INSERT INTO attribute_desc VALUES(1115,1002,'es','Máximamente simétrico','Máximamente simétrico','Un espacio-tiempo es máximamente simétrico si posee el mayor número posible de simetrías continuas del espacio-tiempo (campos de Killing) para su dimensión. En cuatro dimensiones tiene 10 vectores de Killing independientes y curvatura seccional constante. Los espacios-tiempo de Minkowski, de Sitter y anti-de Sitter son las tres soluciones máximamente simétricas de las ecuaciones de Einstein.',NULL);
INSERT INTO attribute_desc VALUES(1116,1002,'en','Metric Affine Connection','$\Gamma*$: Metric-affine connection','A connection for Metric-affine spaces where non-metricity and torsion are not zero.',NULL);
INSERT INTO attribute_desc VALUES(1116,1002,'es','Conexión Métrico-Afín','$\Gamma*$: Conexión afín independiente','Una conexion para espacios métrico-afines donde la no-metricidad y la torsión son distintas de cero.',NULL);
INSERT INTO attribute_desc VALUES(1117,1002,'en','Metric Connection','Metric connection','Also called Levi-Civita connection, it is dependent on the metric $g$. It gives us information about how to transport vectors along a curve, while conserving the metric.',NULL);
INSERT INTO attribute_desc VALUES(1117,1002,'es','Conexión Métrica','Conexión métrica','También llamada la conexión Levi-Civita, es dependiente de la métrica $g$. Nos da información acerca de cómo transportar vectores a lo largo de una curva conservando la métrica.',NULL);
INSERT INTO attribute_desc VALUES(1118,1002,'en','Metric Tensor','$g_{\mu\nu}$: Metric tensor','A symmetric tensor field of type $(0,2)$ and signature $<1,3>$. Provides a sense of distance and angles between vectors telling us about shortest curve.',NULL);
INSERT INTO attribute_desc VALUES(1118,1002,'es','Tensor Métrico','$g_{\mu\nu}$: Tensor métrico','Un campo tensorial simétrico de tipo $(0,2)$. Provee una noción de distancia y ángulo entre vectores. Nos habla de la curva más corta.',NULL);
INSERT INTO attribute_desc VALUES(1119,1002,'en','N','Dimension','The dimension of a manifold is the cardinality of the n-tuples of real numbers that represent points in the manifold.',NULL);
INSERT INTO attribute_desc VALUES(1119,1002,'es','N','Dimensión','La dimensión de una variedad es la cardinalidad de las n-tuplas de números reales que representan puntos en la variedad.',NULL);
INSERT INTO attribute_desc VALUES(1120,1002,'en','n = -2w','$\eta = -2w$',NULL,NULL);
INSERT INTO attribute_desc VALUES(1120,1002,'es','n = -2w','$\eta =-2w$',NULL,NULL);
INSERT INTO attribute_desc VALUES(1121,1002,'en','n = 0','$\eta = 0$',NULL,NULL);
INSERT INTO attribute_desc VALUES(1121,1002,'es','n = 0','$n=0$',NULL,NULL);
INSERT INTO attribute_desc VALUES(1122,1002,'en','n0','$n$','Arbitrary parameter. Sometimes found as $\eta$.',NULL);
INSERT INTO attribute_desc VALUES(1122,1002,'es','n0','$n$','Parámetro arbitrario. También encontrado como $\eta$.',NULL);
INSERT INTO attribute_desc VALUES(1123,1002,'en','Newton-Cartan Connection','$\nabla$: Newton-Cartan connection','Non-flat covariant connection. In Friedman it is found as $D$.',NULL);
INSERT INTO attribute_desc VALUES(1123,1002,'es','Conexión Newton-Cartan','$\nabla$: Conexión Newton-Cartan','Conexión plana covariante.',NULL);
INSERT INTO attribute_desc VALUES(1124,1002,'en','Non Metricity','Non metricity tensor','It measures the failure of the connection to covariantly conserve the metric.',NULL);
INSERT INTO attribute_desc VALUES(1124,1002,'es','No-Metricidad','Tensor de no-metricidad','Mide la falla de la conexión de conservar de forma covariante la métrica.',NULL);
INSERT INTO attribute_desc VALUES(1125,1002,'en','Non Metricity = 0','Non metricity tensor vanishes','Homogeneous Trautman condition.',NULL);
INSERT INTO attribute_desc VALUES(1125,1002,'es','No-Metricidad = 0','No-metricidad = 0','Segunda condición de homogeneidad de Trautman.',NULL);
INSERT INTO attribute_desc VALUES(1126,1002,'en','Non-Local','Non-locality','Matter is a function of density. Nonlocality enters through quantum corrections to the effective field equations from loops of massless gravitons. These induce no macroscopic nonlocality in flat space background because their interactions are suppressed by derivatives.',NULL);
INSERT INTO attribute_desc VALUES(1126,1002,'es','No Local','No-localidad','La materia es función de la densidad. La no localidad entra a través de correcciones cuánticas a las ecuaciones de campo efectivo de bucles de gravitones sin masa. Estos no inducen ninguna no localidad macroscópica en el fondo del espacio plano porque sus interacciones son suprimidas por derivados.',NULL);
INSERT INTO attribute_desc VALUES(1127,1002,'en','Not-Definite-Positive','Class of signature','The class of signature for the metric tensor is not-definite-positive ej: $<-,+,+,+>$ or $<+,-,-,->$.',NULL);
INSERT INTO attribute_desc VALUES(1127,1002,'es','Signatura no toda Positiva','Clase de signatura','Para el tensor métrico: no definitivamente positiva: $<-,+,+,+>$ o $<+,-,-,->$',NULL);
INSERT INTO attribute_desc VALUES(1128,1002,'en','Open','Open Space',NULL,NULL);
INSERT INTO attribute_desc VALUES(1128,1002,'es','Abierto','Espacio Abierto',NULL,NULL);
