INSERT INTO attribute_desc VALUES(1133,1002,'en','Phi','$\phi$: Dynamical scalar field','Rest masses of elementary particles are allowed to vary in spacetime via a dynamical scalar field $\phi$.',NULL);
INSERT INTO attribute_desc VALUES(1133,1002,'es','Phi','$\phi$: Campo escalar dinámico',NULL,NULL);
INSERT INTO attribute_desc VALUES(1134,1002,'en','Phi0','$\phi_{0}$: Cosmological matching parameter','For chosen values for $r$ and $q$, the present values of $w$ and $\Lambda$ are determined by the asymptotic value $\phi_{0}$, which in turn is found through a cosmological solution using the theory. ',NULL);
INSERT INTO attribute_desc VALUES(1134,1002,'es','Phi0','$\phi_{0}$','Parámetro de coincidencia cosmológica.',NULL);
INSERT INTO attribute_desc VALUES(1135,1002,'en','Poincaré Boost','Poincaré Boost',NULL,NULL);
INSERT INTO attribute_desc VALUES(1135,1002,'es','Impulso de Poincaré','Impulso de Poincaré',NULL,NULL);
INSERT INTO attribute_desc VALUES(1136,1002,'en','Poisson Eq 1','Poisson’s Eq','Poisson''s field equation relates the gravitational potential $\Phi$ with the mass density $\rho$, where $del(\Phi)$ is the divergence of the gradient of $\Phi$, and k is the newtonian gravitational constant.',NULL);
INSERT INTO attribute_desc VALUES(1136,1002,'es','Ec. de Poisson','Ec. de Poisson','Esta ecuación describe el potencial gravitacional Φ en términos de densidad de masa ρ y la constante gravitacional G.',NULL);
INSERT INTO attribute_desc VALUES(1137,1002,'en','Poisson Eq 2','Poisson’s Eq in curved space','Poisson''s field equation in curved space relates the Ricci tensor of the connection with the mass density.',NULL);
INSERT INTO attribute_desc VALUES(1137,1002,'es','Ec. de Poisson 2','Ec. de Poisson ','En la teoría Newton-Cartan, esta ecuación relaciona el tensor de Ricci con la densidad de masa ρ y la constante gravitacional G.',NULL);
INSERT INTO attribute_desc VALUES(1138,1002,'en','Preferred point','Preferred point','A a scalar field identifying a preferred point (the center of Earth or the Universe).',NULL);
INSERT INTO attribute_desc VALUES(1138,1002,'es','Punto privilegiado','Punto privilegiado','Un campo escalar que identifica un punto privilegiado (el centro de la Tierra o el centro del Universo).',NULL);
INSERT INTO attribute_desc VALUES(1139,1002,'en','Pressure','Pressure field',NULL,NULL);
INSERT INTO attribute_desc VALUES(1139,1002,'es','Presión','Presión',NULL,NULL);
INSERT INTO attribute_desc VALUES(1140,1002,'en','Proper Time','Proper time',NULL,NULL);
INSERT INTO attribute_desc VALUES(1140,1002,'es','Tiempo propio','Tiempo propio',NULL,NULL);
INSERT INTO attribute_desc VALUES(1141,1002,'en','Psi','$\psi$: Matter fields','$\psi$ represents a collective symbol for various fields or matter degrees of freedom. These fields could represent different types of matter or physical quantities, such as scalar fields, vector fields, or spinor fields, depending on the specific theory. They describe the properties of the physical matter or fields that interact with the gravitational field represented by the metric.',NULL);
INSERT INTO attribute_desc VALUES(1141,1002,'es','Psi','$\psi$: Campos de materia','$\psi$ representa un símbolo colectivo para varios campos o grados de libertad de la materia. Estos campos podrían representar diferentes tipos de materia o cantidades físicas, como campos escalares, campos vectoriales o campos de espinores, según la teoría específica. Describen las propiedades de la materia física o los campos que interactúan con el campo gravitacional representado por la métrica.',NULL);
INSERT INTO attribute_desc VALUES(1142,1002,'en','R = 0','$R=0$','The Ricci scalar is zero.',NULL);
INSERT INTO attribute_desc VALUES(1142,1002,'es','R = 0','$R=0$','El escalar de Ricci es cero.',NULL);
INSERT INTO attribute_desc VALUES(1143,1002,'en','R = Const','$R=Const.$','The Ricci scalar is constant.',NULL);
INSERT INTO attribute_desc VALUES(1143,1002,'es','R = Cte','$R=Cte$','El escalar de Ricci es constante.',NULL);
INSERT INTO attribute_desc VALUES(1144,1002,'en','r, q','$r$, $q$','Arbitrary parameters.',NULL);
INSERT INTO attribute_desc VALUES(1144,1002,'es','r, q','$r$, $q$','Parámetros arbitrarios.',NULL);
INSERT INTO attribute_desc VALUES(1145,1002,'en','R’ = 0','Stationary Universe','El radio del Universo no varía con el tiempo',NULL);
INSERT INTO attribute_desc VALUES(1145,1002,'es','R’ = 0','Universo estacionario',NULL,NULL);
INSERT INTO attribute_desc VALUES(1146,1002,'en','R’ ≠ 0','Dynamic Universe','El radio del Universo varía con el tiempo',NULL);
INSERT INTO attribute_desc VALUES(1146,1002,'es','R’ ≠ 0','Universo dinámico',NULL,NULL);
INSERT INTO attribute_desc VALUES(1147,1002,'en','R(t)x+a(t)','R(t)x+a(t)',NULL,NULL);
INSERT INTO attribute_desc VALUES(1147,1002,'es','R(t)x+a(t)','R(t)x+a(t)',NULL,NULL);
INSERT INTO attribute_desc VALUES(1148,1002,'en','R†','$\Re$: Affine Ricci scalar','The affine Ricci scalar is the trace of the Ricci tensor with respect to the metric and the affine connection, where the Ricci tensor is defined as: $\Re_{\mu\nu}:=\Gamma_{\mu\nu,\lambda}^{*\lambda}-\Gamma_{\mu\lambda,\nu}^{*\lambda}+\Gamma_{\mu\nu}^{*\rho}\Gamma_{\rho\lambda}^{*\lambda}-\Gamma_{\mu\lambda}^{*\rho}\Gamma_{\nu\rho}^{*\lambda}$.',NULL);
INSERT INTO attribute_desc VALUES(1148,1002,'es','R*','$\Re$: Escalar de Ricci afín','El escalar de Ricci afín es la traza del tensor de Ricci con respecto a la métrica y la conección afín. El tensor de Ricci está definido como: $\Re_{\mu\nu}:=\Gamma_{\mu\nu,\lambda}^{*\lambda}-\Gamma_{\mu\lambda,\nu}^{*\lambda}+\Gamma_{\mu\nu}^{*\rho}\Gamma_{\rho\lambda}^{*\lambda}-\Gamma_{\mu\lambda}^{*\rho}\Gamma_{\nu\rho}^{*\lambda}$.',NULL);
INSERT INTO attribute_desc VALUES(1149,1002,'en','Radiation','Radiation',NULL,NULL);
INSERT INTO attribute_desc VALUES(1149,1002,'es','Radiación','Radiación',NULL,NULL);
INSERT INTO attribute_desc VALUES(1150,1002,'en','Ricci < 0','$Ricci=Const<0$','Ricci scalar is constant and negative at all points.',NULL);
INSERT INTO attribute_desc VALUES(1150,1002,'es','Ricci < 0','$Ricci=Const<0$','El escalar de Ricci es constante y negativo en todos los puntos.',NULL);
INSERT INTO attribute_desc VALUES(1151,1002,'en','Ricci > 0','$Ricci=Const>0$','Ricci scalar is constant and positive at all points.',NULL);
INSERT INTO attribute_desc VALUES(1151,1002,'es','Ricci > 0','$Ricci=Const>0$','El escalar de Ricci es constante y positivo en todos los puntos.',NULL);
INSERT INTO attribute_desc VALUES(1152,1002,'en','Ricci Scalar','$R$: Ricci scalar','The Ricci scalar is the trace of the Ricci tensor with respect to the metric and gives a measure of the curvature of space.',NULL);
INSERT INTO attribute_desc VALUES(1152,1002,'es','Escalar de Ricci','$R$: Escalar de Ricci','El escalar de Ricci es la traza del tensor de Ricci con respecto a la métrica y da una medida de la curvatura del espacio.',NULL);
INSERT INTO attribute_desc VALUES(1153,1002,'en','Ricci Tensor','Ricci tensor',NULL,NULL);
INSERT INTO attribute_desc VALUES(1153,1002,'es','Tensor de Ricci','Tensor de Ricci',NULL,NULL);
INSERT INTO attribute_desc VALUES(1154,1002,'en','Rx','Rx',NULL,NULL);
INSERT INTO attribute_desc VALUES(1154,1002,'es','Rx','Rx',NULL,NULL);
INSERT INTO attribute_desc VALUES(1155,1002,'en','Rx+a','Rx+a',NULL,NULL);
INSERT INTO attribute_desc VALUES(1155,1002,'es','Rx+a','Rx+a',NULL,NULL);
INSERT INTO attribute_desc VALUES(1156,1002,'en','Rx+a(t)','Rx+a(t)',NULL,NULL);
INSERT INTO attribute_desc VALUES(1156,1002,'es','Rx+a(t)','Rx+a(t)',NULL,NULL);
INSERT INTO attribute_desc VALUES(1157,1002,'en','Rx+vt+a','Rx+vt+a',NULL,NULL);
INSERT INTO attribute_desc VALUES(1157,1002,'es','Rx+vt+a','Rx+vt+a',NULL,NULL);
INSERT INTO attribute_desc VALUES(1158,1002,'en','Scale factor','Scale factor',NULL,NULL);
INSERT INTO attribute_desc VALUES(1158,1002,'es','Factor de escala','Factor de escala',NULL,NULL);
INSERT INTO attribute_desc VALUES(1159,1002,'en','Sig 1,3','Signature for the metric tensor','We can have $g_{ij}=diag(1,-1,-1,-1)$ at any given point $p\in M$ (but not necessarily on any finite neighborhood of $p$) so long as $g$ has signature $\left\langle 1,3\right\rangle $. A semi-Riemannian manifold whose metric $g$ has this signature is called a Lorentzian manifld (hence, Minkowski space-time is just a flat Lorentzian manifold).',NULL);
INSERT INTO attribute_desc VALUES(1159,1002,'es','Sig 1,3','Signatura del tensor métrico','Podemos tener $g_{ij}=diag(1,-1,-1,-1)$ en cualquier punto dado $p\in M$ (pero no necesariamente en una vecindad finita de $p$) siempre que $g$ tenga signatura $\left\langle 1,3\right\rangle $. Una variedad pseudo-riemanniana cuya métrica $g$ tenga esta signatura será una variedad lorentziana (por lo tanto, el espacio-tiempo de Minkowski es simplemente una variedad lorentziana plana).',NULL);
INSERT INTO attribute_desc VALUES(1160,1002,'en','SM1','Matter action','The action of matter, $S_{M}$, quantifies the dynamics and interactions of matter. It is functional, meaning that it maps a set of fields (in this case, $g_{\mu\nu}$ and $\psi)$ to a real number, typically representing a Lagrangian action or density.',NULL);
INSERT INTO attribute_desc VALUES(1160,1002,'es','SM1','Acción de materia','La acción de la materia, $S_{M}$, cuantifica la dinámica y las interacciones de la materia. Es funcional, lo que significa que asigna un conjunto de campos (en este caso, $g_{\mu\nu}$ y $\psi)$ a un número real, que normalmente representa una acción o densidad lagrangiana.',NULL);
INSERT INTO attribute_desc VALUES(1161,1002,'en','SM2','Affine matter action','The matter action, $S_{M}$, quantifies the behavior of matter fields $\psi)$, their interactions with the metric $(g_{\mu\nu}$, and their coupling to connection coefficients affines $\Gamma_{\mu\nu}^{\lambda}$.',NULL);
INSERT INTO attribute_desc VALUES(1161,1002,'es','SM2','Acción afín de materia','La acción de la materia, $S_{M}$, cuantifica el comportamiento de los campos de materia $\psi)$, sus interacciones con la métrica $(g_{\mu\nu}$ y su acoplamiento a los coeficientes de conexión afines $\Gamma_{\mu\nu}^{\lambda}$.',NULL);
INSERT INTO attribute_desc VALUES(1162,1002,'en','Spatial Homogeneity','Homogeneity','Distribution of objects (particles or galaxies) is homogeneous at large scales',NULL);
INSERT INTO attribute_desc VALUES(1162,1002,'es','Homogeneidad espacial','Homogeneidad','La distribución de objetos (partículas o galaxias) a gran escala es homogénea',NULL);
INSERT INTO attribute_desc VALUES(1163,1002,'en','T = 0','Dust','Energy momentum tensor is almost zero; models for dust.',NULL);
INSERT INTO attribute_desc VALUES(1163,1002,'es','T = 0','Polvo','El tensor de Estrés-Energía-Momentum es casi cero (modelos de polvo).',NULL);
INSERT INTO attribute_desc VALUES(1164,1002,'en','t→f(t)','Arbitrary time transformation',NULL,NULL);
INSERT INTO attribute_desc VALUES(1164,1002,'es','t→f(t)','Transformación arbitraria del tiempo',NULL,NULL);
INSERT INTO attribute_desc VALUES(1165,1002,'en','t→t+tau','Transformation of universal time','A nondynamical scalar field. The gradient of $t$ is covariantly constant and timelike with respect to $\eta$. This scalar field selects out preferred spatial sections of “strata” in the universe that are orthogonal to $\nabla$$t$.',NULL);
INSERT INTO attribute_desc VALUES(1165,1002,'es','t→t+tau','Transformación del tiempo universal','"Un campo escalar no dinámico. El gradiente de $t$ es covariantemente constante y temporal con respecto a $\eta$. Este campo escalar selecciona secciones espaciales preferidas de ""estratos"" en el universo que son ortogonales a $\nabla$."',NULL);
INSERT INTO attribute_desc VALUES(1166,1002,'en','tau','$\tau$','Arbitrary parameter. This represents a constraint on the gauge of the vector field $k_{\mu}$ imposed by the lack of full gauge invariance of the action $I$.',NULL);
INSERT INTO attribute_desc VALUES(1166,1002,'es','tau','$\tau$','Parámetro arbitrario.',NULL);
INSERT INTO attribute_desc VALUES(1167,1002,'en','tau = 0','$\tau=0$','In this case, no constraint is placed on the vector field.',NULL);
INSERT INTO attribute_desc VALUES(1167,1002,'es','tau = 0','$\tau=0$','En este caso, no se impone ninguna restricción al campo vectorial.',NULL);
INSERT INTO attribute_desc VALUES(1168,1002,'en','tau = 1','$\tau=1$','This represents a constraint on the gauge of the vector field $k_{\mu}$ imposed by the lack of full gauge invariance of the action $I$.',NULL);
INSERT INTO attribute_desc VALUES(1168,1002,'es','tau = 1','$\tau=1$','Esto representa una restricción sobre el calibre del campo vectorial $k_{\mu}$ impuesta por la falta de invariancia de calibre total de la acción $I$.',NULL);
INSERT INTO attribute_desc VALUES(1169,1002,'en','Temporal Homogeneity','Temporal homogeneity',NULL,NULL);
INSERT INTO attribute_desc VALUES(1169,1002,'es','Homogeneidad Temporal','Homogeneidad temporal',NULL,NULL);
INSERT INTO attribute_desc VALUES(1170,1002,'en','Tensor Degeneration','Tensor degeneration','When the constitutive tensor degenerates into $(\epsilon,\mu^{-1})$, the field equations become $\nabla\times E=-\frac{1}{c}\frac{\partial B}{\partial t}$, $\nabla\cdot B=0$,<br>$\nabla\times H=-\frac{1}{c}\frac{\partial D}{\partial t}+\frac{4\pi}{c}j$, $\nabla\cdot D=4\pi\rho$.',NULL);
INSERT INTO attribute_desc VALUES(1170,1002,'es','Degeneración Tensorial','Degeneración tensorial','Cuando el tensor constitutivo degenera en $(\epsilon,\mu^{-1})$, las ecuaciones de campo se convierten en $\nabla\times E=-\frac{1}{c}\frac{\partial B}{\partial t}$, $\nabla\cdot B=0$,<br>$\nabla\times H=-\frac{1}{c}\frac{\partial D}{\partial t}+\frac{4\pi}{c}j$, $\nabla\cdot D=4 \pi\rho$.',NULL);
INSERT INTO attribute_desc VALUES(1171,1002,'en','Time','Time','$T$ is an interval of real line.<br>Every $t$ represents an instant of time.<br>The relation $\leq$ that orders $T$ means “earlier than or simultaneous with.”',NULL);
INSERT INTO attribute_desc VALUES(1171,1002,'es','Tiempo','Tiempo','$T$ es un intervalo de línea real.<br>Cada $t$ representa un instante de tiempo.<br>La relación $\leq$ que ordena $T$ significa “más temprano que, o simultáneo a”.',NULL);
INSERT INTO attribute_desc VALUES(1172,1002,'en','Time like Geodesics','Geodesic law','Free particles follow timeline geodesics of the connection.',NULL);
INSERT INTO attribute_desc VALUES(1172,1002,'es','Geodésicas tipo tiempo','Ley Geodésica','Las partículas libres siguen las geodésicas de la línea tipo tiempo de la conexión.',NULL);
INSERT INTO attribute_desc VALUES(1173,1002,'en','Tmn','$T_{\mu\nu}$: Stress-Energy-Momentum tensor','A $(2,0)$ symmetric tensor field representing the energy-momentum of the mass distribution, with specific energy density contributions from interactions dictated by theories.',NULL);
INSERT INTO attribute_desc VALUES(1173,1002,'es','Tmn','$T_{\mu\nu}$: Tensor de Estrés-Energía-Momentum','Un campo tensor simétrico $(2,0)$ que representa el momento de energía de la distribución de masa, con contribuciones específicas de densidad de energía de las interacciones dictadas por las teorías.',NULL);
INSERT INTO attribute_desc VALUES(1174,1002,'en','Torsion','Cartan torsion tensor','The anti-symmetric part of the connection.',NULL);
INSERT INTO attribute_desc VALUES(1174,1002,'es','Torsión','Tensor de torsión de Cartan','La parte antisimétrica de la conexión.',NULL);
INSERT INTO attribute_desc VALUES(1175,1002,'en','Torsion = 0','Torsion = 0','Cartan''s torsion tensor vanishes. Homogeneous Trautman Condition $\widetilde{R}_{bd}^{ac}=\widetilde{R}_{db}^{ca}$.',NULL);
INSERT INTO attribute_desc VALUES(1175,1002,'es','Torsión = 0','Torsión = 0','El tensor de torsión de Cartan se desvanece. Condición de homogeneidad de Trautman. $\widetilde{R}_{bd}^{ac}=\widetilde{R}_{db}^{ca}$.',NULL);
INSERT INTO attribute_desc VALUES(1176,1002,'en','Universal Time','Universal Time',NULL,NULL);
INSERT INTO attribute_desc VALUES(1176,1002,'es','Tiempo universal','Tiempo universal',NULL,NULL);
INSERT INTO attribute_desc VALUES(1177,1002,'en','Vacuum','Vacuum',NULL,NULL);
INSERT INTO attribute_desc VALUES(1177,1002,'es','Vacío','Vacío',NULL,NULL);
INSERT INTO attribute_desc VALUES(1178,1002,'en','Vector field','Distinguished Tangent Vector Field','A tangent vector field that forms part of the defining structure of a spacetime or cosmological model. Its integral curves determine a preferred family of reference worldlines. In Newtonian spacetime this is Friedman''s rigging field $V$; in relativistic cosmological models it is the four-velocity field $u^{a}$ of the fundamental observers.',NULL);
INSERT INTO attribute_desc VALUES(1178,1002,'es','Campo vectorial','Campo Vectorial Tangente Distinguido','Un campo vectorial tangente que forma parte de la estructura definitoria de un modelo de espacio-tiempo o cosmológico. Sus curvas integrales determinan una familia privilegiada de líneas de universo de referencia. En el espacio-tiempo newtoniano, se trata del campo de anclaje $V$ de Friedman; en los modelos cosmológicos relativistas, es el campo de cuadrivelocidad $u^{a}$ de los observadores fundamentales.',NULL);
INSERT INTO attribute_desc VALUES(1179,1002,'en','w','$w(\phi)$: Arbitrary coupling function',NULL,NULL);
INSERT INTO attribute_desc VALUES(1179,1002,'es','w','$w(\phi)$: Función arbitraria de acoplamiento',NULL,NULL);
INSERT INTO attribute_desc VALUES(1180,1002,'en','w = 0','$w=0$','The coupling function $w(\phi)$ is zero.',NULL);
INSERT INTO attribute_desc VALUES(1180,1002,'es','w = 0','$w=0$',NULL,NULL);
INSERT INTO attribute_desc VALUES(1181,1002,'en','w-inf','$w\rightarrow\infty$','In this limit the Brans-Dicke theory reduces to general relativity.',NULL);
INSERT INTO attribute_desc VALUES(1181,1002,'es','w-inf','$w\rightarrow\infty$',NULL,NULL);
INSERT INTO attribute_desc VALUES(1182,1002,'en','w’ = 0','$w’=0$',NULL,NULL);
INSERT INTO attribute_desc VALUES(1182,1002,'es','w’ = 0','$w’=0$',NULL,NULL);
INSERT INTO attribute_desc VALUES(1183,1002,'en','w0, w1','$w_{0}, w_{1}$','Cosmological matching parameters',NULL);
INSERT INTO attribute_desc VALUES(1183,1002,'es','w0, w1','$w_{0}, w_{1}$','Parámetros de coincidencia cosmológica.',NULL);
INSERT INTO attribute_desc VALUES(1184,1002,'en','Weitzenbock','Weitzenböck donnection',NULL,NULL);
INSERT INTO attribute_desc VALUES(1184,1002,'es','Witzenbock','Conexión de Weitzenböck',NULL,NULL);
INSERT INTO attribute_desc VALUES(1185,1002,'en','Weyl Vector','Weyl vector','The Weyl vector is the trace of the non-metricity tensor with respect to its last two (symmetric) indices.',NULL);
INSERT INTO attribute_desc VALUES(1185,1002,'es','Vector de Weyl','Vectror de Weyl','La traza del tensor de no-metricidad con respecto a sus dos últimos índices simétricos.',NULL);
INSERT INTO attribute_desc VALUES(1186,1002,'en','Weyl Vector = 0','Weyl vector vanishes','The trace of the non-metricity tensor with respect to its last two (symmetric) indices is equal to zero.',NULL);
INSERT INTO attribute_desc VALUES(1186,1002,'es','Vector de Weyl = 0','El vector de Weyl se desvanece','La traza del tensor de no metricidad con respecto a sus dos últimos índices (simétricos) es igual a cero.',NULL);
INSERT INTO attribute_desc VALUES(1187,1002,'en','x→phi(x)','x→phi(x)',NULL,NULL);
INSERT INTO attribute_desc VALUES(1187,1002,'es','x→phi(x)','x→phi(x)',NULL,NULL);
INSERT INTO attribute_desc VALUES(1188,1002,'en','Xi','Mendoza’s tensor','Where $L_{M}^{2}$ defines a length fixed by the parameters of the theory: $L_{M}:=\zeta(\frac{GM}{a_{0}^{3}})^{\frac{1}{4}}$.',NULL);
INSERT INTO attribute_desc VALUES(1188,1002,'es','Xi','Tensor de Mendoza ','Donde $L_{M}^{2}$ define una longitud fijada por los parámetros de la teoría: $L_{M}:=\zeta(\frac{GM}{a_{0}^{3}})^{\frac{1}{4}}$.',NULL);
INSERT INTO attribute_desc VALUES(1189,1002,'en','Xi†','Mendoza''s affine tensor','Where $\Re$ is a non traditional Ricci scalar (affine Ricci scalar) and $L_{M}:=\zeta(\frac{GM}{a_{0}^{3}})^{\frac{1}{4}}$.',NULL);
INSERT INTO attribute_desc VALUES(1189,1002,'es','Xi*','Tensor afín de Mendoza','Donde $\Re$ es un escalar de Ricci no tradicional (escalar de Ricci afín) y $L_{M}:=\zeta(\frac{GM}{a_{0}^{3}})^{\frac{1}{4}}$.',NULL);
INSERT INTO attribute_desc VALUES(1190,1002,'en','Λ ','Cosmological function','$\lambda(\phi)$ causes two effects: in the field equation for $g$ it plays the same role as the cosmological constant in GR, and, in the field equation, it gives $(\phi)$ a range l related to $\lambda$, $w$ and their derivatives, in the sense that the solutions for $(\phi)$ for an isolated system contain Yukawa-like terms $exp\left(-r/l\right)$.',NULL);
INSERT INTO attribute_desc VALUES(1190,1002,'es','Λ ','Función cosmológica','$\lambda(\phi)$ provoca dos efectos: en la ecuación de campo para $g$ juega el mismo papel que la constante cosmológica en GR y, en la ecuación de campo, da a $(\phi)$ un rango l relacionado con $\lambda$, $w$ y sus derivados, en el sentido de que las soluciones para $(\phi)$ para un sistema aislado contienen términos tipo Yukawa $exp\left(-r/l\right)$.',NULL);
INSERT INTO attribute_desc VALUES(1191,1002,'en','Λ < 0','Cosmological constant is negative',NULL,NULL);
INSERT INTO attribute_desc VALUES(1191,1002,'es','Λ < 0','Constante cosmológica negativa',NULL,NULL);
INSERT INTO attribute_desc VALUES(1192,1002,'en','Λ = 0','Cosmological function vanishes','Nordtvedt''s (1970b) scalar-tensor theory is equivalent to the Bergmann-Wagoner theory in the special case of zero cosmological function $\lambda\equiv0$.',NULL);
INSERT INTO attribute_desc VALUES(1192,1002,'es','Λ = 0','$\lambda(\phi)=0$',NULL,NULL);
INSERT INTO attribute_desc VALUES(1193,1002,'en','Λ > 0','Cosmological constant is positive ',NULL,NULL);
INSERT INTO attribute_desc VALUES(1193,1002,'es','Λ > 0','Constante cosmológica posittiva',NULL,NULL);
INSERT INTO attribute_desc VALUES(1194,1002,'en','ρ=0','Zero density',NULL,NULL);
INSERT INTO attribute_desc VALUES(1194,1002,'es','ρ=0','Densidad cero',NULL,NULL);
INSERT INTO attribute_desc VALUES(1195,1002,'en','ρ>0','Positive density',NULL,NULL);
INSERT INTO attribute_desc VALUES(1195,1002,'es','ρ>0','Densidad positiva',NULL,NULL);
